(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0013.js"] = [{"id":"glyph-kai-96ea","script":"kai","character":"雪","reading":"xuě","description":"xuě：(1)天空中飘落的白色结晶体，多为六角形，是天空中的水蒸气冷至摄氏零度以下凝结而成～花。～山。～中送炭（喻在别人遇到困难时及时给予帮助）。\n(2)洗去，除去报仇～恨。为国～耻。平反昭～。\n(3)擦拭晏子独笑于旁，公～涕而顾晏子”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雪"},{"id":"glyph-kai-96f3","script":"kai","character":"雳","reading":"lì","description":"见“霹雳”，雷电产生的强烈雷声，也比喻突然发生的震动人心的事。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-96f6","script":"kai","character":"零","reading":"líng","description":"líng：(1)液体降落感激涕～。\n(2)植物凋谢～落。凋～。～散（sàn）。\n(3)整数以外的尾数～数儿。\n(4)部分的，细碎的，与整”相对～碎。～卖。～钱。～售。～乱。～工。～打碎敲。\n(5)整数系统中一个重要的数，小于一切自然数，是介于正数和负数之间唯一的数，记作０”。有时用来表示某种量的基准，如摄氏温度计上的冰点，记作０℃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-零"},{"id":"glyph-kai-96f7","script":"kai","character":"雷","reading":"léi","description":"léi：(1)由于下雨时带异性电的两块云相接，空中闪电发出的强大的声音～电。～鸣。～动。～雨。～霆。～厉风行。\n(2)军事用的爆炸武器地～。鱼～。布～。扫～。～管。\n(3)姓。\n〔～池〕古水名，在今中国安徽省望江县。现用于成语不敢越～～一步”，喻不敢越出一定的范围。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雷"},{"id":"glyph-kai-96f9","script":"kai","character":"雹","reading":"báo","description":"báo：空中水蒸气遇冷结成的冰粒或冰块，常在夏季随暴雨下降冰～。～子。～灾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雹"},{"id":"glyph-kai-96fe","script":"kai","character":"雾","reading":"wù","description":"接近地面的空气中的水蒸气\n像雾的许多小水滴\n比喻轻细的\n比喻浓密的\n昏晦,昏暗\n⒈飘浮在近地面空气中的大量小水滴或冰晶，主要是水蒸气遇冷后凝结而成大～弥江。\n⒉像雾的东西吐～。喷～洒水。\n雾méng 1.昏暗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雾"},{"id":"glyph-kai-9700","script":"kai","character":"需","reading":"xū","description":"xū：(1)必得用～求。～要。必～。急～。\n(2)必得用的财物军～。民～。\n(3)等待。\n(4)迟疑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-需"},{"id":"glyph-kai-9704","script":"kai","character":"霄","reading":"xiāo","description":"xiāo：(1)云云～。～汉（ａ．云霄和天河，指天空ｂ．古代喻朝廷）。\n(2)天空九～。重（chóng）～。～壤（天和地，喻相去很远）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霄"},{"id":"glyph-kai-9707","script":"kai","character":"震","reading":"zhèn","description":"zhèn：(1)疾雷（霹雳）使物体振动～夷伯之庙”。～霆。\n(2)雷烨烨～电。”\n(3)巨大的力等使物体剧烈颤动～撼。～荡。～颤。～响。～动。声～遐迩。\n(4)迅速或剧烈地颤动地～。身子不由得一～。\n(5)特指地震”～灾。～源。～中。～级。～情。防～。抗～。余～。\n(6)惊恐或情绪过分激动～惊。～怒。～骇。～慑。\n〔～旦〕佛教经籍中的译名，指中国。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-震"},{"id":"glyph-kai-9709","script":"kai","character":"霉","reading":"méi","description":"méi：(1)低等植物，真菌的一类，常寄生在食物和衣服的表面，呈细丝状，有分枝，没有叶绿素～菌。白～。青～。\n(2)食品、衣物等受了潮热长霉菌发～。～烂。～变。～气。～豆腐。\n〔倒（dǎo）～〕遇事不利，遭遇不好。亦作倒楣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霉"},{"id":"glyph-kai-970d","script":"kai","character":"霍","reading":"huò","description":"huò：(1)快，迅速～闪（闪电）。～地。～然。\n(2)姓。\n〔～～〕ａ．形容摩擦声、鸟翅振动声、笑声等；ｂ．形容快速闪动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霍"},{"id":"glyph-kai-970e","script":"kai","character":"霎","reading":"shà","description":"shà：(1)小雨～～（形容雨声）。\n(2)极短的时间～时。～那。一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霎"},{"id":"glyph-kai-971c","script":"kai","character":"霜","reading":"shuāng","description":"shuāng：(1)附着在地面或植物上面的微细冰粒，是接近地面的水蒸气冷至摄氏零度以下凝结而成的～降。～冻。～序（指深秋季节）。～秋。～期。～天。\n(2)像霜一样的东西柿～。西瓜～。\n(3)形容白色～鬓。～刃。～锋。\n(4)喻高洁～操（高洁的节操）。～骨。～情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霜"},{"id":"glyph-kai-971e","script":"kai","character":"霞","reading":"xiá","description":"xiá：日出或日落时天空云层因受日光斜射而呈现的光彩朝（zhāo）～。晚～。彩～。云～。～帔。～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霞"},{"id":"glyph-kai-9732","script":"kai","character":"露","reading":"lù；lòu","description":"lù：凝结在物体上的小水滴；显现，如露水、暴露。lòu：口语中指显现出来，如露头、露脸。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9738","script":"kai","character":"霸","reading":"bà","description":"bà：(1)指依杖权势或武力欺压他人的人或集团～王。称～。恶～。\n(2)奉行强力政策，或实行强力占有～占。～权。～道。～略。\n(3)古代称诸侯的盟主～主（ａ．中国春秋时势力最大并取得首领地位的诸侯；ｂ．在某一领域或地区称霸的人或集团）。～业。春秋五～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霸"},{"id":"glyph-kai-9739","script":"kai","character":"霹","reading":"pī","description":"pī：〔～雳〕响声极大的雷。\n〔～雷〕即霹雳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霹"},{"id":"glyph-kai-9752","script":"kai","character":"青","reading":"qīng","description":"qīng：(1)深绿色或浅蓝色～绿。～碧。～草。～苔。～苗。～菜。～葱。～山绿水。～云直上。万古长～（喻高尚的精神或深厚的友情永远不衰）。\n(2)绿色的东西踏～。～黄不接。\n(3)靛蓝色靛～。～紫。～出于蓝，胜于蓝。\n(4)黑色～布。～线。～衫。～衣。\n(5)喻年轻～年。～春。～工。\n(6)竹简～简。～史（原指写在竹简上的记事，后指史书，如永垂～～”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-青"},{"id":"glyph-kai-9756","script":"kai","character":"靖","reading":"jìng","description":"jìng：(1)平安，安静～冥（幽深闲静）。～默。\n(2)平定，使秩序安定绥～。～难（nàn）（平定叛乱）。\n(3)图谋，谋议实～夷我邦”。\n(4)恭敬士处～，敬老与贵，交不失礼。”\n(5)古同静”，静止。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靖"},{"id":"glyph-kai-9759","script":"kai","character":"静","reading":"jìng","description":"jìng：(1)停止的，与动”相对～止。～态。～物。平～。风平浪～。\n(2)没有声音安～。寂～。僻～。冷～。肃～。～悄悄。～穆。～谧。～默。～观。～听。\n(3)安详，闲雅～心。～坐。\n(4)古同净”，清洁。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-静"},{"id":"glyph-kai-975e","script":"kai","character":"非","reading":"fēi","description":"fēi：(1)不，不是～凡。～法。～分（fèn）。～礼。～但。～同小可。啼笑皆～。\n(2)不对，过失痛改前～。文过饰～。习～成是（对于某些错的事情习惯了，反认为是对的）。\n(3)与不”呼应，表示必须（有时后面没有不”字）我～看这本书。\n(4)责怪，反对～难（nàn）。～议。无可厚～。\n(5)指阿非利加洲”（位于东半球的西南部。简称非洲”）东～。西～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-非"},{"id":"glyph-kai-9760","script":"kai","character":"靠","reading":"kào","description":"kào：(1)倚着，挨近倚～。～垫。～背。船～岸。\n(2)依赖依～。～托。～头。\n(3)信托可～。～得住。牢～。\n(4)传统戏剧中武将所穿的铠甲扎～。～旗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靠"},{"id":"glyph-kai-9761","script":"kai","character":"靡","reading":"mí","description":"mí：(1)浪费，奢侈～荡。～费。侈～。\n(2)分散～散（消灭）。\n(3)古同糜”，糜烂。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靡"},{"id":"glyph-kai-9762","script":"kai","character":"面","reading":"miàn","description":"⒈脸，头的前部～孔。颜～。～不改色。\n⒉直接接触，当着本人在场～谈。当～说。\n⒊朝着，脸对着～向。～山而居。\n⒋部位，方向前～。里～。右～。四～八方。～ ～俱到。\n⒌东西的外表地～。鞋～子。被盖～儿。\n⒍几何学上指线移动所生成的形迹，有长有宽没有厚～积。平～。\n⒎量词三～旗帜。两～镜子。\n①脸面，面子没有～目见人。\n②相貌，脸的形状～目可憎。\n③〈喻〉事物的景象状态～目一新。\n①体面怕丢～子。\n②情面秉公执法，不讲～子。\n③东西的外表桌～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-面"},{"id":"glyph-kai-9769","script":"kai","character":"革","reading":"gé","description":"gé：(1)去了毛经过加工的兽皮皮～。～履（皮鞋）。～囊。\n(2)改变～新。～命（ａ．原意是改变命运；ｂ．现指改变社会制度、建立新社会的群众运动；ｃ．亦指改造旧技术、旧思想的运动）。改～。变～。\n(3)取消，除掉～除。～职。～故鼎新（去除旧的，建立新的）。\n(4)中国古代乐器八音之一，如鼓等。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-革"},{"id":"glyph-kai-9774","script":"kai","character":"靴","reading":"xuē","description":"xuē：有长筒的鞋～子。马～。皮～。棉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靴"},{"id":"glyph-kai-9776","script":"kai","character":"靶","reading":"bǎ","description":"bǎ：(1)练习射箭或射击用的目标～子。～场。～标。打～。\n(2)缰绳。\n(3)供加速器、原子核反应堆、放射性源等发出的粒子流轰击的实物样品，用以研究核反应，获得放射性同位素或产生Ｘ射线等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-靶"},{"id":"glyph-kai-978b","script":"kai","character":"鞋","reading":"xié","description":"xié：穿在脚上便于走路的东西皮～。～袜。～帮。～面。～底。～油。～匠。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞋"},{"id":"glyph-kai-978d","script":"kai","character":"鞍","reading":"ān","description":"ān：套在骡马背上便于骑坐的东西马～。～鞒。～韂（chàn）（马鞍和垫在马鞍下面的东西。亦称鞍鞯”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞍"},{"id":"glyph-kai-97a0","script":"kai","character":"鞠","reading":"jū；jv","description":"jū：(1)养育，抚养～育。～养。\n(2)弯曲～躬。～躬尽瘁。\n(3)大，穷极～凶。\n(4)幼小～子（稚子）。\n(5)穷困尔惟～自苦”。\n(6)告诫陈师～旅”。\n(7)古代的一种皮球蹴～。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞠"},{"id":"glyph-kai-97ad","script":"kai","character":"鞭","reading":"biān","description":"biān：(1)驱使牲畜的用具，柔软像绳子～杆。～长莫及。\n(2)用鞭子抽打～打。～扑。～责。～策。\n(3)形状细长类似鞭子的东西教～。\n(4)一种古代兵器，铁制有节，无锋刃钢～。竹节～。\n(5)编连成串的爆竹～炮。小～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鞭"},{"id":"glyph-kai-97e7","script":"kai","character":"韧","reading":"rèn","description":"韧劲,韧劲儿","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韧"},{"id":"glyph-kai-97e9","script":"kai","character":"韩","reading":"hán","description":"井上的木栏\n古国名\n中国周朝时的一个诸侯国,在今山西省韩城县\n战国七雄之一◇为秦所灭。今山西省东部和河南省西北部\n1897╠1910年朝鲜的国名","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韩"},{"id":"glyph-kai-97ed","script":"kai","character":"韭","reading":"jiǔ","description":"jiǔ：〔～菜〕多年生草本植物，叶细长而扁，夏秋间开凶花；叶和花嫩时可食，种子可入药。简称韭”，如～黄”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韭"},{"id":"glyph-kai-97f3","script":"kai","character":"音","reading":"yīn","description":"yīn：(1)声，亦特指有节奏的声声～。～乐（yuè）。～律。～色。～量。～区。～韵。～像。～容（声音、容貌）。弦外之～。\n(2)信息，消息～信。佳～。～讯。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-音"},{"id":"glyph-kai-97f5","script":"kai","character":"韵","reading":"yùn","description":"yùn：(1)汉语字音中的元音或元音加收尾音，即声母以外的部分，或声母和介音以外的部分，称韵母”。如ｔ幔睿绲脑夏甘轻ｎｇ”，ｈｕ幔睿绲脑夏甘牵踽ｎｇ”～文（有韵律节奏的文学体裁，亦指用这种体裁写成的文章，包括诗、词、歌、赋等。区别于散文”）。押～。～腹（韵母中主要元音）。～脚（韵文句末押韵的字）。～律（诗词中的平仄格式和押韵的规则）。\n(2)和谐而有节奏的～白。琴～悠扬。\n(3)风度，风致，情趣，意味风～。气～。～味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-韵"},{"id":"glyph-kai-9875","script":"kai","character":"页","reading":"yè","description":"书页\n量词\n一般指两面印刷的书籍、杂志、资料等印刷品的一张纸的一面。如一本三百页的书;第一页\n也指书籍、杂志、报纸、信件或类似物件的一张纸。如撕下其中的一页\n⒉量词。\n页xié 1.头。脑袋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-页"},{"id":"glyph-kai-9876","script":"kai","character":"顶","reading":"dǐng","description":"①人体或物体的最高部分头～、屋～。\n②用头支承～碗。\n③自下而上用力拱起幼芽～出土。\n④用头撞击被羊～了一个跟头。\n⑤顶撞。\n⑥对面迎着～风。\n⑦支撑；抵住～门杠、～住敌人多次进犯。\n⑧相当一人～两人用。\n⑨顶替～名。\n【顶点】\n①最高点；极点。\n②〈数〉三角形中顶角的两条边的交点或锥体的尖顶。\n【顶端优势】〈生〉植物的顶芽抑制侧芽生长的现象。农业上常用消除或维持顶端优势的办法控制作物、果树和花木的生长，以利增产和控制花木株形的目的。\n【顶技】一种杂技。表演者用身体一些部位顶直棍棒，或在棍棒顶端放置易碎物品而保持平衡使其不落地。\n【顶天立地】形容豪迈正大的英雄气概。\n【顶细胞】指被子植物二细胞原胚时期上部的一个细胞。\n【顶芽】位于茎的主轴或侧枝顶端的芽。单轴分枝树木主轴的顶芽生长旺盛，有的顶芽可形成花芽，如苹果、梨等。\n【顶真】〈语〉修辞学上辞格之一。用前文结尾的词语或词组做下文的起头，使语句递接紧凑而生动畅达。如'茵茵牧草绿山坡，山坡畜群似云朵，云朵游动笛声起，笛声悠扬\n卷浪波。'\n【顶珠】〈语〉见【顶真】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顶"},{"id":"glyph-kai-9877","script":"kai","character":"顷","reading":"qǐng","description":"通倾”。倾斜;偏侧\n頃顷\n田地面积的单位,等于一百亩\n⒈地积单位。1百市亩＝1市～＝6.6667公～。\n⒉时间短，跟\"久\"相对～刻。俄～。有～。少～。\n⒊刚才～闻。～接家书。\n⒋〈古〉通\"倾\"。侧，斜～耳。\n顷qīng 1.同\"倾\"。头不正。 2.同\"倾\"。倾斜;偏侧。 3.同\"倾\"。倾注。 4.同\"倾\"。倾覆。 5.同\"倾\"。古指妇人专擅国政。谓不正规，非正统。 6.姓『代有顷宪","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顷"},{"id":"glyph-kai-9879","script":"kai","character":"项","reading":"xiàng","description":"泛指人颈\n代数中不用加、减号连接的单式\n款项\n⒈颈子的后部。泛指颈部～背。屈～。引～高歌。\n⒉事物的分类或条目事～。～目。八～注意。\n⒊钱，经费款～。收入～。\n⒋量词两～任务。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-项"},{"id":"glyph-kai-987a","script":"kai","character":"顺","reading":"shùn","description":"顺从;顺应\n⒈向着同一个方向，跟\"逆\"相对～水。～应。～风而呼。～于民心。\n⒉沿，循，依次～大路走。因雨～延。～次前进。\n⒊随，趁便～便。～手关电。～口而出。\n⒋整理，使有条理理～头发。这篇文章，还要～一～。\n⒌适合，符合心意～眼。～心。～意。\n⒍服从～从。～着。\n⒎匀和风调雨～。\n⒏道理通达，符合事理～理。名正言～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顺"},{"id":"glyph-kai-987b","script":"kai","character":"须","reading":"xū","description":"野兽的魀。泛指动、\n①须要务～注意、必～努力。\n②姓。\n⒉等待；等到。\n①原来指长在下巴上的胡子，后来泛指胡须～发、～眉。\n②须子触～、花～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-须"},{"id":"glyph-kai-987d","script":"kai","character":"顽","reading":"wán","description":"愚顽之人;顽固派\n凶恶的人\n引申为浑圆\n顽固,不驯服\n⒈愚蠢无知愚～。痴～。笨～。\n⒉固执，守旧～固。～梗。\n⒊淘气～皮。～童。\n⒋〈古〉凶暴，贪婪～贪。\n⒌通\"玩\"。游戏，耍弄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顽"},{"id":"glyph-kai-987e","script":"kai","character":"顾","reading":"gù","description":"⒈回头看瞻前～后。〈引〉看左～右盼。环～四周。\n⒉注意，照管，关心～全大局。照～。关～。奋不～身。\n⒊探望，拜访三～茅庐。\n⒋商店称来买货物的善待～客。优惠老～主。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顾"},{"id":"glyph-kai-987f","script":"kai","character":"顿","reading":"dùn","description":"用脚底或用脚使劲往下踩\n倒下,跌倒\n①稍停停～。\n②忽然；立刻～悟。\n③用头或手叩地～首。\n④处理；安置安～。\n⑤量词。用于吃饭、劝说等行为的次数三～饭。\n⑦姓。\n【顿挫】停顿转折。多形容声音和谐悦耳，节奏感强。\n【顿号】标点符号的一种，即'、'，表示一句话中并列的词或词组之间的停顿。\n【顿开茅塞】见【茅塞顿开】。\n【顿然】忽然；一下子。\n【顿首】叩头；磕头。旧时多用于书信的起头或末尾。\n顿dú 1.见\"冒顿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-顿"},{"id":"glyph-kai-9881","script":"kai","character":"颁","reading":"bān","description":"又假借为攽”。颁发;分赏\n出御府珠玉玩好之物,颁\n颁 bān 颁布；发～奖。\n【颁行】发布施行。\n颁fén 1.大头貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颁"},{"id":"glyph-kai-9882","script":"kai","character":"颂","reading":"sòng","description":"这个意义后来写作容”\n占兆之词\n文体之一,指\n⒈赞扬，赞美～扬。歌～。\n⒉棕祝～。敬～。\n⒊一种文体，以赞扬为内容的诗歌或文章祖国～。\n⒋〈古〉在祭祀中使用的舞曲周～。鲁～。\n颂róng 1.仪容。 2.容受;收容。 3.宽容。 4.公开;明白。参见\"颂言\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颂"},{"id":"glyph-kai-9884","script":"kai","character":"预","reading":"yù","description":"预先,事先。事先有准备。通豫”\n参与。通与”\n⒈在先，事前～先。～告。～言。～计。～约。～定。～防。～祝胜利。\n⒉加入，参加，参与～会。参～。干～其事。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-预"},{"id":"glyph-kai-9885","script":"kai","character":"颅","reading":"lú","description":"头,头颅\n额头\n颅盖\n颅骨\n颅腔","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颅"},{"id":"glyph-kai-9886","script":"kai","character":"领","reading":"lǐng","description":"领子,衣领\n要领\n山道,山坡\n⒈脖子引～北望。\n⒉衣服上围绕脖子的部分衣～子。\n⒊要点，纲要要～。纲～。提纲挈～。\n⒋带，引，统率～队。带～。率～。～兵百万。\n⒌接受，取得～教。失物招～。\n⒍了解，懂得，欣赏～会。～悟。～略。共～人间第一香。\n⒎占有，管辖占～。～土。～海。～空。～域。\n⒏量词锦裘三～。四～凉席。\n①率领并引导。\n②指领导人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-领"},{"id":"glyph-kai-9887","script":"kai","character":"颇","reading":"pō","description":"偏,倾斜,不平正\n偏邪,不公正\n⒈偏，偏差偏～。\n颇pǒ 1.不可。\n颇pí 1.参见\"颇我\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颇"},{"id":"glyph-kai-9888","script":"kai","character":"颈","reading":"jǐng","description":"器物像颈或部位相当于颈的部分\n脖子的前面部分\n⒈俗称\"脖子\"，头与躯干相连的部分引～高歌。\n⒉物体像颈的部分瓶～。\n颈gěng 1.见\"脖颈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颈"},{"id":"glyph-kai-988a","script":"kai","character":"颊","reading":"jiá","description":"侧,旁边\n堂内正室旁边的房间\n颊带","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颊"},{"id":"glyph-kai-9891","script":"kai","character":"频","reading":"pín","description":"接近;临近\n并列\n重复,连续\n危急;紧急\n⒈屡次，连续多次～繁。捷报～传。～～招手。\n⒉［频仍］连续不断，一再重复。\n⒊［频率］\n②在一定的时间或范围内事物重复出现或反复发生的次数。\n频bīn 1.水边。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-频"},{"id":"glyph-kai-9893","script":"kai","character":"颓","reading":"tuí","description":"委靡,消沉\n衰老\n詈词。恶劣之意\n⒈崩塌，倒塌～塌。～垣断壁。〈喻〉灭亡倾～。\n⒉跌倒～堕。\n⒊落，落下，水向下流日～。水～。泣涕如～。\n⒋委靡，衰败～丧。～唐。～颜。～风败俗。\n①建筑物倒塌。\n②精神委糜不振。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颓"},{"id":"glyph-kai-9896","script":"kai","character":"颖","reading":"yǐng","description":"锥芒\n⒈谷穗，禾的末端。稻、麦等禾本科植物小穗基部的苞片嘉禾重～。谷之～片。\n⒉东西末端的尖锐部分锥在袋中，～脱而出。\n⒊聪明幼便～悟。聪～过人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颖"},{"id":"glyph-kai-9897","script":"kai","character":"颗","reading":"kē","description":"多用于圆形或粒状物\n如三颗黄豆;两颗绿豆\n颗kē量词。指圆形或粒状物一～红心。三～珠子。五～星。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颗"},{"id":"glyph-kai-9898","script":"kai","character":"题","reading":"tí","description":"物品的前端或顶端\n⒊练习、考试等要求解答的问问～。试～。数学～。\n⒋写上，签署～写。～名。～款。～词。\n⒌评议品～。\n题dì 1.通\"睇\"。视。 2.通\"匙\"。歃血器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-题"},{"id":"glyph-kai-989c","script":"kai","character":"颜","reading":"yán","description":"印堂,两眉之间\n额头\n面容,脸色\n体面,容誉\n⒈额～赤。〈引〉面容，容貌～面⊥～悦色。笑逐～开。无～见人。\n⒉色彩～色。～料。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颜"},{"id":"glyph-kai-989d","script":"kai","character":"额","reading":"é","description":"店铺或厅堂正面和顶部挂的有字的板,牌匾\n规定的数目\n①人脸眉毛之上头发之下的部分。也指某些动物头部与人额相当的部分。俗称脑门子。\n②牌匾门～。\n③规定的数量定～、超～。\n【额外价值】见【剩余价值】。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-额"},{"id":"glyph-kai-98a0","script":"kai","character":"颠","reading":"diān","description":"泛指物体的顶部\n马的额头\n本,始\n古县名\n②同'巅'，高而直立的东西的顶端山～。\n③上下振动～簸。\n④跌落；倒下～覆。\n⑤同'癫'，神经错乱。\n【颠覆】采用阴谋手段从内部推翻合法政权。\n【颠沛流离】生活困苦，四处流浪。\n【颠扑不破】无论怎样摔打都弄不破。比喻思想、理论正确，无法驳倒。\n颠tián 1.见\"颠颠\"。 2.通\"阗\"。充满。参见\"颠实\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颠"},{"id":"glyph-kai-98a4","script":"kai","character":"颤","reading":"chàn","description":"颤抖,发抖\n物体振动\n通惮”。惧怕,惊恐\n⒈振动～动。\n颤zhàn发抖，极其害怕～栗。打～‘～。胆～心惊。～ ～兢兢。\n颤shān 1.鼻通能辨气味。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-颤"},{"id":"glyph-kai-98ce","script":"kai","character":"风","reading":"fēng","description":"空气流动形成的自然现象。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-kai-98d8","script":"kai","character":"飘","reading":"piāo","description":"飘扬,飞扬\n⒈旋风，大风～风。\n⒉随风摆动或飞扬～动。～摇。～扬。桂花～香§旗～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飘"},{"id":"glyph-kai-98de","script":"kai","character":"飞","reading":"fēi","description":"泛指飞翔\n⒈鸟类或虫类等利用翅膀在空中活动小鸟群～。～蛾←蝶～。〈引〉物体在空中飘扬或行动，又指这些物体彩云～。大雪纷～。～砂走石。火箭起～。～行物。宇宙～船\n⒉快，极其迅速～步。～报。～舟。～腾。～跃。\n⒊极，非常这把剑～快。\n⒋形容高悬在空中的～桥。\n⒍意外的～祸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-飞"},{"id":"glyph-kai-98df","script":"kai","character":"食","reading":"shí；sì；yì","description":"shí：(1)吃～肉。～欲。\n(2)吃的东西～品。粮～。零～。丰衣足～。\n(3)俸禄君子谋道不谋～”。\n(4)日月亏缺或完全不见的现象日～。月～。\nsì：拿东西给人吃～母（乳母）。\nyì：用于人名郦～其（jī）（中国汉代人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-食"},{"id":"glyph-kai-9910","script":"kai","character":"餐","reading":"cān","description":"cān：(1)吃～具。～厅。聚～。风～露宿。\n(2)饭食早～。西～。\n(3)量词，指一顿饭一日三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-餐"},{"id":"glyph-kai-9965","script":"kai","character":"饥","reading":"jī","description":"⒈饿，跟\"饱\"相对～饿难熬。～肠辘辘。～不择食。\n⒉灾荒，年收成不好～荒。～岁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饥"},{"id":"glyph-kai-996d","script":"kai","character":"饭","reading":"fàn","description":"给人喂饭或喂牲口\n含。古代将米贝珠玉之类放\n⒈熟的谷物食品，多指大米饭这～好吃。这～好香哟！\n⒉进食，定时吃的食品能～否？开～了。吃晚～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饭"},{"id":"glyph-kai-996e","script":"kai","character":"饮","reading":"yǐn","description":"⒈喝～茶。～酒。～水思源。水浊不可～。\n⒉可以喝的东西～料。冷～。\n⒊含，忍～泣。～恨。\n饮yìn给牲口喝水～马渭水。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饮"},{"id":"glyph-kai-9970","script":"kai","character":"饰","reading":"shì","description":"装饰;修饰\n⒈装修得好看装～。修～。粉～。\n⒉指装饰品首～。服～。\n⒊假托，遮掩～词。掩～。文过～非。\n⒋扮演她在这个剧里～主角。\n饰chì 1.整治;整顿。 2.端正;谨慎。 3.戒备。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饰"},{"id":"glyph-kai-9971","script":"kai","character":"饱","reading":"bǎo","description":"充足,多\n饱满\n满足\n既醉以酒,既饱以德。\n①食量得到了满足，与'饿'相反吃～喝足。\n②饱满谷淋～。\n③丰富；充分～学之士、～经忧患。\n④满足大～眼福。\n【饱和化合物】饱和烃及其衍生物。其分子中碳-碳原子间完全以单键相连结。\n【饱和链烃】见【烷烃】。\n【饱和汽】如果汽跟产生这种汽的液体处于动态平衡状态时，这种汽就称为该液体的饱和汽。\n【饱和溶液】在一定温度下，溶液里所溶解的某种溶质如果不能再增加，这样的溶液称为这种溶质的饱和溶液。饱和溶液处于溶解平衡状态。\n【饱经风霜】经历过长时期艰苦生活的磨练。\n【饱食终日】吃得饱饱地打发日子。形容无所事事。\n【饱学】学识丰富～之士。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饱"},{"id":"glyph-kai-9972","script":"kai","character":"饲","reading":"sì","description":"饲养,给动物吃东西\n粮食\n指饲料\n饲sì喂食～料。～蚕。～养鸡鸭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饲"},{"id":"glyph-kai-9975","script":"kai","character":"饵","reading":"ěr","description":"钓鱼用的鱼食\n药饵\n食物的总称\n筋腱\n吞食\n①糕饼果～。\n②钓鱼用的鱼食鱼～。\n③引诱以此～敌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饵"},{"id":"glyph-kai-9976","script":"kai","character":"饶","reading":"ráo","description":"富裕,丰足\n余;剩\n⒉宽容，宽恕～恕。～他这一次。\n⒊添～上两元。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饶"},{"id":"glyph-kai-997a","script":"kai","character":"饺","reading":"jiǎo","description":"饺jiǎo面皮包馅做成半圆形的食品水～。蒸～子。锅贴～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饺"},{"id":"glyph-kai-997c","script":"kai","character":"饼","reading":"bǐng","description":"形状像饼的东西\n做饼\n饼铛\n饼肥\n饼干\n饼子\n用玉米面、小米面等贴在锅上\n①烤熟或蒸熟的面食的总称。形状多扁且圆～干、烤～。\n②形状像饼的东西铁～、柿～。\n【饼饵】饼类食品的泛称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饼"},{"id":"glyph-kai-997f","script":"kai","character":"饿","reading":"è","description":"使受饿;感到饥饿\n①肚子没食，想吃东西。\n②使受饿别～着。\n【饿莩】见【饿殍】。\n【饿殍】饿死的人。又作饿莩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-饿"},{"id":"glyph-kai-9981","script":"kai","character":"馁","reading":"něi","description":"气馁;泄气,丧气\n⒈饥饿冻饿冻～。〈喻〉失掉勇气气～。胜不骄败不～。\n⒉鱼腐烂，不新鲜鱼～而肉败。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馁"},{"id":"glyph-kai-9985","script":"kai","character":"馅","reading":"xiàn","description":"面食、糕点里包的豆沙、糖、果仁、果肉或切碎的肉、菜等填料\n被包裹的人或物\n比喻事情的底细,隐密\n馅xiàn包在米粉、面食等内部的甜或咸心子芝麻～。豆沙～。三鲜～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馅"},{"id":"glyph-kai-9986","script":"kai","character":"馆","reading":"guǎn","description":"⒈接待宾客或旅客居住或食宿的房屋宾～。旅～。\n⒉某些服务性的商店饭～。茶～儿。美容～。\n⒊外交人员在别国常驻的处所领事～。大使～。\n⒋展示物品、陈列文物或进行文化活动的场所展览～。博物～。文化～。图书～。科技～。\n⒌〈古〉教书的地方蒙～。家～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馆"},{"id":"glyph-kai-9988","script":"kai","character":"馈","reading":"kuì","description":"进食\n烹调\n赠送\n⒈赠送～赠。\n⒉吃饭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馈"},{"id":"glyph-kai-998b","script":"kai","character":"馋","reading":"chán","description":"贪图;贪羡\n①看见好吃的食物就忍不住想吃；专爱吃好的～猫、～嘴。\n②羡慕；贪。\n【馋涎欲滴】馋得口水都快滴下来了。形容馋到了极点。也比喻对某种东西极想占有。\n⒈贪吃，专挑好的吃～嘴。贪官嘴～。\n⒉贪，羡慕眼～手痒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馋"},{"id":"glyph-kai-998d","script":"kai","character":"馍","reading":"mó","description":"饼类食品","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馍"},{"id":"glyph-kai-998f","script":"kai","character":"馏","reading":"liú","description":"通过加热使物质分离或分解\n馏liù将凉的熟食蒸热把包子～一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馏"},{"id":"glyph-kai-9992","script":"kai","character":"馒","reading":"mán","description":"馒头","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馒"},{"id":"glyph-kai-9996","script":"kai","character":"首","reading":"shǒu","description":"shǒu：(1)头，脑袋～饰。～级。～肯（点头表示同意）。\n(2)领导的人，带头的～领。元～。～脑。～相（xiàng）。\n(3)第一，最高～都（dū）。～府。\n(4)最先，最早～次。～届。～创。～日封。～义（首先起义）。\n(5)出头告发自～。出～。\n(6)量词，指诗和歌一～诗。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-首"},{"id":"glyph-kai-9999","script":"kai","character":"香","reading":"xiāng","description":"xiāng：(1)气味好闻，与臭”相对～味。～醇。芳～。清～。\n(2)舒服睡得～。\n(3)味道好这鱼做得真～。\n(4)受欢迎这种货物在农村～得很。\n(5)称一些天然或人造的有香味的东西麝～。灵猫～。龙涎～。檀～。沉～。\n(6)旧时用以形容女子事物或作女子的代称～闺。～艳。\n(7)祭祖、敬神所烧的用木屑搀上香料做成的细条～火。烧～拜佛。～炉。～烛。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-香"},{"id":"glyph-kai-99a8","script":"kai","character":"馨","reading":"xīn","description":"xīn：(1)散布很远的香气～香。如兰之～。\n(2)喻长存的英名垂～千祀。\n(3)助词，作用同样”宁～（这样，如此）。宁～儿（原意是这样的儿子”，后用以赞美孩子或子弟）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-馨"},{"id":"glyph-kai-9a6c","script":"kai","character":"马","reading":"mǎ","description":"单蹄食草大型哺乳动物\n⒈家畜。耳小直立，面长，颈上缘有鬃，尾巴有长毛，四肢强健，善跑，供人骑或拉东西等。皮可制革。\n⒉通\"码\"筹～。\n⒑［马到成功］战马一到就胜利了。形容迅速地取得胜利。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-马"},{"id":"glyph-kai-9a6e","script":"kai","character":"驮","reading":"tuó","description":"驮着货物的牲口或牲口所负载的货物\n负载\n⒈用背负载马～着盐巴。她背上～了个孩子。\n驮duò 1.驮着货物的牲口或指牲口所驮的货物。 2.量词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驮"},{"id":"glyph-kai-9a6f","script":"kai","character":"驯","reading":"xùn","description":"泛指顺服\n⒈顺从，听从指使～服。善于～兽。\n⒉善良～行。\n驯xún 1.马顺服。 2.泛指顺服。 3.使驯服，使和顺。 4.顺，不背理﹑不乱。 5.调顺，使和谐不乱。 6.美善。 7.循序渐进。 8.熟习。 9.通\"训\"。教训，教导\n。 10.通\"训\"。训释，解说。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驯"},{"id":"glyph-kai-9a70","script":"kai","character":"驰","reading":"chí","description":"又驱使\n疾行\n②传扬～名中外。\n【驰名】声名远扬。又作驰誉。\n【驰誉】见【驰名】。\n【驰骤】奔驰纵横～。\n⒈奔跑，使劲赶马。〈引〉车马疾行奔～。～骋。疾～。特指驱马进击将～之。\n⒉向往心～神往。\n⒊传扬～名中外。\n驰tuó 1.参见\"橐驰\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驰"},{"id":"glyph-kai-9a71","script":"kai","character":"驱","reading":"qū","description":"赶马\n并驱从两牡兮。\n冯谖先\n⒈赶马。〈引〉赶，赶走～马。～虫。～逐。～车前进。\n⒉快跑驰～。并驾齐～。长～直入。\n①差遣，迫使～使他去干。\n②推动为好奇心所～使。\n驱ōu 1.捶击，殴打。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驱"},{"id":"glyph-kai-9a73","script":"kai","character":"驳","reading":"bó","description":"驳杂;庞杂\n①指出对方的意见不合事理或无道理；用自己的意见否定别人的意见反～。\n②一种颜色夹杂着别种颜色；不纯净斑～陆离。\n③驳运；在岸与船，船与船之间用小船来回运输～运。\n④驳船。无动力装置，由拖轮拉着或推着行驶的船铁～。\n【驳船】分装、转运货物或旅客的船只，一般无动力装置，而由拖轮推、拉航行。\n【驳回】指法院拒绝诉讼当事人、法定代理人或检察院提出的申请和要求。\n【驳论】议论方法之一。即直接揭露某事物的错误本质，批驳某主张的反动性质，痛斥某行为的严重桅。特点是措辞激烈，笔锋犀利，逻辑性强，语言一针见血，多用反问句\n、判断句、否定句。\n【驳难】反驳责难。\n【驳杂】不纯净，杂乱论文内容～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驳"},{"id":"glyph-kai-9a74","script":"kai","character":"驴","reading":"lǘ；lv","description":"驴不胜怒。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驴"},{"id":"glyph-kai-9a76","script":"kai","character":"驶","reading":"shǐ","description":"疾速\n驾驶,行驶;驱使\n使者。也作使”\n⒈马快跑，跑疾～。奔～。\n⒉开动，操纵～车。驾～。军舰～入海洋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驶"},{"id":"glyph-kai-9a79","script":"kai","character":"驹","reading":"jū；jv","description":"泛指少壮的马\n⒈好马千里～。\n驹jù 1.见\"驹丽\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驹"},{"id":"glyph-kai-9a7b","script":"kai","character":"驻","reading":"zhù","description":"古时特指车驾停立\n驻zhù 1.车马停止。 2.停留。 3.止住;阻止。 4.留住。 5.居留其地。 6.指居住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驻"},{"id":"glyph-kai-9a7c","script":"kai","character":"驼","reading":"tuó","description":"成块的东西。也作坨”\n人身体背部向后成拱形的\n用牲口负物。也作驮”\n其兽则\n⒈骆驼。\n⒉身体前曲，背脊突起如骆驼峰的样子～背。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驼"},{"id":"glyph-kai-9a7e","script":"kai","character":"驾","reading":"jià","description":"把鞍加在马背上\n骑;乘\n操纵;驾驶\n晓驾炭车辗\n①对人员的管理及使用。\n②掌握，控制知识越多，～驭的能力越强。\n驾jiā 1.添加;增多。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-驾"},{"id":"glyph-kai-9a82","script":"kai","character":"骂","reading":"mà","description":"增益。通雈”\n痛斥\n⒈用粗野的话侮辱人辱～。莫～人。\n⒉用严厉的话斥责～了他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骂"},{"id":"glyph-kai-9a84","script":"kai","character":"骄","reading":"jiāo","description":"骄 〈形〉\n马雄壮,泛指高大雄壮\n傲慢;骄矜\n⒉自满，自高自大～傲自满。～兵必败。戒～戒躁。〈引〉放纵～奢淫逸。\n⒊猛烈～阳灼人。\n①自高自大，瞧不起别人～傲使人落后。\n②自豪祖国的～傲。值得～傲。\n骄xiāo 1.犬名。参见\"歇骄\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骄"},{"id":"glyph-kai-9a86","script":"kai","character":"骆","reading":"luò","description":"哔哔骆马。\n骆驼\n通络”。络绎不绝\n骆jià 1.见\"骆田\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骆"},{"id":"glyph-kai-9a87","script":"kai","character":"骇","reading":"hài","description":"惊骇;惊诧;惊动\n震动\n骇hài马受惊马～。〈引〉惊恐，害怕惊涛～浪。～人听闻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骇"},{"id":"glyph-kai-9a8c","script":"kai","character":"验","reading":"yàn","description":"证据;凭证\n效验,灵验\n征象;征兆\n检查;检验\n⒈检查，察看～血。～光。～收。～证。\n⒉效果效～。应～。\n⒊〈古〉证据，凭证何以为～？","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-验"},{"id":"glyph-kai-9a8f","script":"kai","character":"骏","reading":"jùn","description":"天子赐许男骏马十六。\n才能出众的人\n迅速\n⒈好马～马。八～日行三万里。〈引〉急速～奔。\n⒉〈古〉通\"峻\"。高而陡峭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骏"},{"id":"glyph-kai-9a91","script":"kai","character":"骑","reading":"qí","description":"跨于物上或两边叫骑,跨坐\n⒈两腿跨坐在牲畜或其它东西上～马。～驴。～摩托车。\n⒉骑的马或其它牲畜坐～。\n⒊指骑兵轻～。铁～。也泛指骑马的人单～。\n⒋兼跨两边～缝盖章。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骑"},{"id":"glyph-kai-9a97","script":"kai","character":"骗","reading":"piàn","description":"跃上马背而骑乘;骑。同騗”\n欺骗;哄劝\n超越;跨越\n引诱,吸引\n⒈欺蒙，说假话欺～。～人。\n⒉用欺骗手段谋取～取。～局。诓～。诈～犯。算命～人钱财。\n⒊跨过去，跳跃上去一～腿上了船。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骗"},{"id":"glyph-kai-9a9a","script":"kai","character":"骚","reading":"sāo","description":"骚动;动乱\n通搔”。抓,挠,以指甲轻刮\n其人坚劲,寡有疥骚,终无瘠酲。╠\n⒈动乱，扰乱，不安定～动。～乱。～扰。\n⒊同\"臊\"。一种臭味，特指狐腋臭～气。\n②原指姿容俏丽，后多指妇女言行轻佻。\n骚sǎo 1.全部;尽数。\n骚xiāo 1.地名用字。蒲骚，春秋地名，在今湖北省应城市西北。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骚"},{"id":"glyph-kai-9aa1","script":"kai","character":"骡","reading":"luó","description":"动物名。骡子","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骡"},{"id":"glyph-kai-9aa4","script":"kai","character":"骤","reading":"zhòu","description":"使马奔驰\n泛指奔驰\n迅疾,猛快\n飘风不终朝,骤雨不终\n⒈马奔驰弛～。〈引〉急速，快速暴风～雨。\n⒉忽然，突然～然。狂风～起。天色～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骤"},{"id":"glyph-kai-9aa8","script":"kai","character":"骨","reading":"gǔ；gū","description":"gǔ：(1)人和脊惟动物身体里面支持身体保护内脏的坚硬组织～头。～胳（全身骨头的总称）。～节。～肉（ａ．指最亲近的有血统关系的人，亦称骨血”；ｂ．喻紧密相连，不可分割的关系）。～干（gàn）。\n(2)像骨的东西（指支撑物体的骨架）伞～。扇～。\n(3)指文学作品的理论和笔力～力（ａ．雄健的笔力；ｂ．刚强不屈的气概）。风～（古典文艺理论术语，指文章的艺术风格，亦指作品的风神骨髓）。\n(4)指人的品质、气概侠～。～气。\ngū：〔～朵儿（duor）〕尚未开放的花朵。\n〔～碌〕滚动（碌”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-骨"},{"id":"glyph-kai-9ad3","script":"kai","character":"髓","reading":"suǐ","description":"suǐ：(1)骨头的空腔中像胶状的东西骨～。精～（喻精华）。\n(2)像骨髓的东西脊～。脑～。延～（后脑的一部分）。\n(3)植物茎的中心部分，由薄壁的细胞组成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-髓"},{"id":"glyph-kai-9ad8","script":"kai","character":"高","reading":"gāo","description":"gāo：(1)由下到上距离大的，与低”相对～峰。～空。～踞。～原。～耸。～山流水（喻知己、知音或乐曲高妙）。～屋建瓴（形容居高临下的形势）。～瞻远瞩。\n(2)高度他身～一米八。\n(3)等级在上的～级。～考。\n(4)在一般标准或平均程度之上～质量。～消费。～价。～档。～手。～能物理。\n(5)声音响亮引吭～歌。\n(6)敬辞，称别人的事物～见。～就。～论。～寿。～堂。～徒。\n(7)热烈、盛大～昂。兴～采烈。\n(8)显贵，道德水平高崇～。清～。～风亮节。～尚。～雅。～洁。\n(9)宗族中最在上之称～祖。\n(10)酸根或化合物中比标准酸根多含一个氧原子的～锰酸钾。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-高"},{"id":"glyph-kai-9b13","script":"kai","character":"鬓","reading":"bìn","description":"鬓发\n鬓角\n鬓脚\n鬓 bìn鬓角。耳朵前边长头发的部位。也指长在那里的头发双～斑白。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬓"},{"id":"glyph-kai-9b3c","script":"kai","character":"鬼","reading":"guǐ","description":"guǐ：(1)某些宗教或迷信的人所说的人死后的灵魂～魂。～魅。～蜮（ａ．鬼怪；ｂ．阴险害人的）。\n(2)阴险，不光明～话。～黠。～胎。\n(3)对人的蔑称或憎称酒～。烟～。～子。吝啬～。\n(4)恶劣，糟糕（限做定语）～天气。\n(5)机灵，敏慧（多指小孩子）～精灵。\n(6)表示爱昵的称呼小～。机灵～。\n(7)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鬼"},{"id":"glyph-kai-9b41","script":"kai","character":"魁","reading":"kuí","description":"kuí：(1)为首的，居第一位的～首。～星（ａ．北斗星中第一星，又第一星至第四星的总称；ｂ．中国神话中所说的主宰文章兴衰的神）。～元。罪～祸首。夺～。\n(2)高大身～力壮。～梧。～伟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魁"},{"id":"glyph-kai-9b42","script":"kai","character":"魂","reading":"hún","description":"hún：(1)迷信的人指附在人体上主宰人，又可离开肉体而独立存在的实体～灵。鬼～。～不附体。\n(2)指精神或情绪～飞魄散（形容极度惊恐）。～不守舍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魂"},{"id":"glyph-kai-9b44","script":"kai","character":"魄","reading":"pò","description":"pò：(1)指依附形体而存在的精神魂～。丢魂落～。魂飞～散。\n(2)精神，精力～力。气～。体～。\n(3)古同霸”，月始生或将灭时的微光。\n(4)古同粕”，糟粕。\n(5)古同珀”，琥珀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魄"},{"id":"glyph-kai-9b45","script":"kai","character":"魅","reading":"mèi","description":"mèi：传说中的鬼怪鬼～。\n〔～力〕很能吸引人的力量。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魅"},{"id":"glyph-kai-9b4f","script":"kai","character":"魏","reading":"wèi","description":"wèi：(1)古代宫门上的楼台～阙（古代宫门上所建的巍然高出的台阙，因下边两旁有悬布法令的地方，所以亦用来代指朝廷）。\n(2)中国周代诸侯国名，在今河南省北部、陕西省东部、山西省西南部和河北省南部等地。\n(3)中国历史上的三国之一。\n(4)中国历史上的北朝之一北～。～碑（北朝碑刻的统称）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魏"},{"id":"glyph-kai-9b54","script":"kai","character":"魔","reading":"mó","description":"mó：(1)宗教或神话传说中指害人性命、迷惑人的恶鬼，喻邪恶的势力～王。～爪。～怪。～鬼。～掌。～窟。恶～。妖～。病～。\n(2)不平常，奇异的～力。～术。～怔（举动异常，像有精神病。怔”读轻声）。～法。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-魔"},{"id":"glyph-kai-9c7c","script":"kai","character":"鱼","reading":"yú","description":"完全水生并在水中呼吸的有头冷血脊椎动物,包括圆口类、板鳃类和具有软骨或硬骨骨骼的高等有鳃水生脊椎动物\n养～致富。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鱼"},{"id":"glyph-kai-9c81","script":"kai","character":"鲁","reading":"lǔ","description":"迟钝,愚钝\n莽撞,粗野\n中国春秋时国名\n⒈笨，愚钝～钝。\n⒊周代诸侯国名，在今山东省南部一带。\n⒋山东省的简称。\n鲁lǚ 1.陈述。 2.旅行。参见\"鲁飔\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲁"},{"id":"glyph-kai-9c8d","script":"kai","character":"鲍","reading":"bào","description":"盐腌的鱼\n鲍鱼,鳆鱼的别名。即石决明\n腹足纲前鳃亚纲鲍科鲍属海产贝类\n古代鞣制皮革的工人\n鲍老\n①见【鲍鱼】。\n②姓。\n【鲍叔牙】春秋时齐国大夫。生卒年不详。以能了解别人著称。少时与管仲友善。襄公乱政时，随公子凶出奔莒，凶成为国君后欲任鲍叔牙为宰，他却力举管仲◇齐国在管仲治理下，成为霸主。\n【鲍鱼】\n①咸鱼。\n②软体动物，贝类。生活在海中，肉可食，贝壳入中药。\n鲍bāo 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲍"},{"id":"glyph-kai-9c9c","script":"kai","character":"鲜","reading":"xiān","description":"假借为鱻。鲜鱼,活鱼\n鲜美的食物\n⒈新的，不干枯的～花。～鱼。～笋。～血。新～。尝～。\n⒉味美～汤。\n⒊鱼、虾等产品河～。～。\n⒋光彩，明亮～艳。～红。～明。\n鲜xiàn 1.通\"献\"。进献。 2.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲜"},{"id":"glyph-kai-9ca4","script":"kai","character":"鲤","reading":"lǐ","description":"鲤鱼\n一种软鳍淡水鱼,素栖于池塘或缓流中,主要吃植物性食物,可长得相当大,有时能活得很长,原为亚洲产物\n书信的代称\n鲤庭\n鲤lǐ鱼名。鲤鱼体侧扁，嘴边有长短须各一对。生活在淡水中，它是常见的养殖鱼类之一，供食用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲤"},{"id":"glyph-kai-9ca8","script":"kai","character":"鲨","reading":"shā","description":"吹沙鱼\n鲨鱼\n瘤子,显得很粗糙,吻部突出于嘴的前边,两边都有鳃孔,雄鱼有鳍脚和伸长的腹鳍\n鲨shā鱼名。鲨鱼又作\"沙鱼\"，也叫\"鲛\"。种类很多，性凶猛，捕食其它鱼类。生活在海洋里。肉可吃，肝可制鱼肝油，皮可制革，骨可制胶。鳍叫\"鱼翅\"，是珍贵的食品。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲨"},{"id":"glyph-kai-9cab","script":"kai","character":"鲫","reading":"jì","description":"鲫鱼,亦称鲋”\n鲫溜\n鲫jì鲫鱼，体侧扁，背脊隆起，无触须，头小，背青褐色，腹银白色。生活在淡水中，供食用。变种\"金鱼\"供观赏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲫"},{"id":"glyph-kai-9cb8","script":"kai","character":"鲸","reading":"jīng","description":"大;巨大\n鲸波\n⒈鱼名。鲸鱼，属受保护的动物，禁止猎杀。它是生活在海洋里的哺乳动物，形状像鱼，胎生，肺呼吸，鼻孔位于头顶部。大小因种而异，小的长约一米；大的可达三十米，是\n现在世界上最大的动物。肉可吃，肝可制鱼肝油，脂肪可做油。\n鲸qíng 1.水栖哺乳纲动物。体形长大，外形似鱼，小约1米，大至30米。头大，眼小，耳壳退化。前肢呈鳍状，后肢退化。尾鳍叉形，呈水平状。成体皮肤无毛，皮下脂肪增\n厚，用肺呼吸，可潜水一刻钟至一小时。胎生。皮﹑肉﹑脂肪均可利用。鲸的种类很多，如蓝鲸﹑抹香鲸﹑海豚﹑江豚以及我国特有的淡水海豚即白暨豚等都属于鲸类。 2.指","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鲸"},{"id":"glyph-kai-9cc4","script":"kai","character":"鳄","reading":"è","description":"鳄鱼\n钝吻鳄的俗称\n宽吻鳄的俗称\n鳄鱼扳手\n鳄鱼夹\n鳄 è一种凶猛的爬行动物。头部扁平，吻和尾很长，四肢短，体被有角质鳞。善于游泳，捕食鱼、蛙、鸟类。多产于热带或亚热带。俗称鳄鱼。\n【鳄鱼的眼泪】古代西方传说，鳄鱼一边吞食人畜，一边落泪。比喻坏人的假慈悲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳄"},{"id":"glyph-kai-9ccd","script":"kai","character":"鳍","reading":"qí","description":"鳍qí鱼类及其它水生脊椎动物的运动器官。一般由薄膜、柔软分节的\"鳍条\"和坚硬不分节的\"鳍棘\"构成背～。腹～。尾～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳍"},{"id":"glyph-kai-9cd6","script":"kai","character":"鳖","reading":"biē","description":"北各地,多栖于池沼、河沟、稻田中,肉味鲜美,一般认为是补品\n鳖 biē爬行纲，鳖科。生活在水中，背甲长可达24厘米，一般为橄榄色，腹面乳白色。肉可食用，鳖甲可入药。又称甲鱼或团鱼。有的地区叫鼋。俗称王八。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳖"},{"id":"glyph-kai-9cde","script":"kai","character":"鳞","reading":"lín","description":"鳞片状物\n动物学名词。为被覆在动物体表的硬质小形薄片,是一种多样性的\n⒈鱼类、爬行动物和少数哺乳动物等体表上的角质或骨质的小薄片鱼～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鳞"},{"id":"glyph-kai-9e1f","script":"kai","character":"鸟","reading":"niǎo","description":"⒈脊椎动物的一类。全身有羽毛，前肢变为翅，后肢能行走，用肺呼吸，温血卵生，能飞爱护～儿。千山～飞绝。也有因翅退化不能飞的，如鸵～。\n①从高处往下看登高～瞰河山。\n②事物的概括描写～瞰国际形势。\n鸟diǎo 1.人﹑畜的雄性生殖器。多用为詈词。\n鸟què 1.地名用字。参见\"鸾鸟\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸟"},{"id":"glyph-kai-9e21","script":"kai","character":"鸡","reading":"jī","description":"家禽，有多种品种，可供食用或产蛋；雄鸡常在清晨啼叫。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9e23","script":"kai","character":"鸣","reading":"míng","description":"泛指发声\n⒈禽兽或虫叫鸡～。鹿～。蝉～。\n⒉发响，使发响雷～。自～钟。～礼炮。\n⒊〈表〉感情，喊叫～谢。～不平。～冤叫屈。\n⒋表达意见、主张等百家争～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸣"},{"id":"glyph-kai-9e25","script":"kai","character":"鸥","reading":"ōu","description":"水鸟名","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸥"},{"id":"glyph-kai-9e26","script":"kai","character":"鸦","reading":"yā","description":"比喻黑色\n需经高级医师处方，慎重使用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸦"},{"id":"glyph-kai-9e2d","script":"kai","character":"鸭","reading":"yā","description":"水禽名。俗称鸭子\n对其妻有外遇者的称呼\n鸭yā水鸟名。分家～和野～，嘴扁，颈长，脚短，趾间有蹼，善游泳。野鸭会飞。通常指家鸭，不能高飞，可成群饲养，肉、卵供食用，鸭绒供做衣、被等。已有人工饲养野～","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸭"},{"id":"glyph-kai-9e2f","script":"kai","character":"鸯","reading":"yāng","description":"见“鸳鸯”，一种水鸟；“鸯”在传统称谓中指雌鸟。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9e33","script":"kai","character":"鸳","reading":"yuān","description":"比喻同事,同僚","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸳"},{"id":"glyph-kai-9e35","script":"kai","character":"鸵","reading":"tuó","description":"鸵鸟\n自欺欺人者,行径类似传说中鸵鸟般的人;可联想到驼鸟习性的人\n人工养殖，供食用。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸵"},{"id":"glyph-kai-9e3d","script":"kai","character":"鸽","reading":"gē","description":"鸽派\n他们是国会中鸽派代表,常常反对鹰派的冷战主张\n鸽哨\n空中划过一串清脆的鸽哨声\n鸽子","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸽"},{"id":"glyph-kai-9e3f","script":"kai","character":"鸿","reading":"hóng","description":"鹄。即天鹅\n喻指\n⒈大型雁类的泛称。\n⒊大～文。～图。\n鸿hòng 1.见\"鸿絧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鸿"},{"id":"glyph-kai-9e43","script":"kai","character":"鹃","reading":"juān","description":"见“杜鹃”，鸟名，也称子规；“杜鹃”也指一种开花植物。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9e45","script":"kai","character":"鹅","reading":"é","description":"鹅 é家禽。像鸭但比鸭大，颈长，喙扁阔，脚有蹼。羽毛白色或灰色，额部有橙黄色或黑褐色肉质突起，雄的突起较大。能游泳，吃谷物、蔬菜、鱼虾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹅"},{"id":"glyph-kai-9e49","script":"kai","character":"鹉","reading":"wǔ","description":"见“鹦鹉”，鸟类，喙弯曲，羽色多样，有些种类能模仿人声。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-9e4a","script":"kai","character":"鹊","reading":"què","description":"鸦科的鹊属和若干其他属的许多鸟之一,它与松鸦亲缘关系密切,但有一长而分等级的尾,体羽通常为黑色和白色","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹊"},{"id":"glyph-kai-9e4f","script":"kai","character":"鹏","reading":"péng","description":"比喻前程远大\n雄伟,伟大\n⒈〈古〉传说中的一种大鸟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹏"},{"id":"glyph-kai-9e64","script":"kai","character":"鹤","reading":"hè","description":",羽毛更紧密,部分秃顶,嘴较钝并在近中央处有较大鼻孔,后趾向上抬起\n比喻白色\n鹤hè鸟儿，要保护，禁止猎杀。它的头小，颈和脚细长，嘴长而直，翼大善飞，羽毛白色或灰色。常见的是白～，又叫\"仙～\"、\"丹顶～\"。羽毛白色，头顶红色，叫声高而清脆\n。捕食鱼、虾等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹤"},{"id":"glyph-kai-9e66","script":"kai","character":"鹦","reading":"yīng","description":"鸟名,鹦鹉。俗称鹦哥”\n鹦哥\n鹦鹉\n酒器名\n鹦鹉学舌\n要保护，禁止猎杀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹦"},{"id":"glyph-kai-9e70","script":"kai","character":"鹰","reading":"yīng","description":"种鸟\n比喻爪牙\n形容勇猛,激进\n鹰yīng鸟名。种类很多，常见的有苍～、雀～、鸢～等，均已少见，要保护，禁止猎杀。鹰上嘴弯曲尖锐，趾有锐利的钩爪，性凶猛，捕食鼠类和其它鸟类等。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹰"},{"id":"glyph-kai-9e7f","script":"kai","character":"鹿","reading":"lù","description":"lù：(1)哺乳动物，四肢细长，尾短。雄鹿头上有树枝状的角。毛多为棕褐色，有的有花斑或条纹。听觉和嗅觉都很灵敏。种类很多，常见的有梅花鹿、水鹿、白唇鹿、马鹿等。\n(2)方形的粮仓市无赤米，而囷～空虚。”\n(3)粗，粗劣～裘。～布。～床。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鹿"},{"id":"glyph-kai-9ea6","script":"kai","character":"麦","reading":"mài","description":"造纸原料","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-麦"},{"id":"glyph-kai-9ebb","script":"kai","character":"麻","reading":"má","description":"má：(1)草本植物，种类很多，有大麻”、苎麻”、苘麻”、亚麻”等。茎皮纤维通常亦称麻”，可制绳索、织布～布。～衣。～袋。～绳。～纺。\n(2)指芝麻”～酱。～油。\n(3)像腿、臂被压后的那种不舒服的感觉脚～了。\n(4)感觉不灵，或丧失感觉，引申为思想不敏锐～痹。～醉。～木不仁。\n(5)面部痘瘢，引申指物体表面粗糙～子。\n(6)带细碎斑点的～雀。～蝇。\n(7)喻纷乱～乱。～沸。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-麻"},{"id":"glyph-kai-9ec4","script":"kai","character":"黄","reading":"huáng","description":"huáng：(1)像金子或向日葵花的颜色～色。～昏。牛～。～澄澄。信口雌～。\n(2)特指中国黄河～灾。治～。～泛区。\n(3)指黄帝”（即轩辕氏”，传说中原始社会部落联盟首领）～老（黄帝和老子）。炎～子孙。\n(4)事情失败或计划不能实现事情～了。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-黄"},{"id":"glyph-kai-9ece","script":"kai","character":"黎","reading":"lí","description":"lí：(1)众，众多～民。～庶。\n(2)古通黧”，黑色。\n(3)古国名。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-黎"},{"id":"glyph-kai-9ed1","script":"kai","character":"黑","reading":"hēi","description":"hēi：(1)像墨和煤那样的颜色，与白”相对～白。\n(2)暗，光线不足～暗。～夜。\n(3)隐蔽的，非法的～枪。～市。～社会。\n(4)恶毒～心。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-黑"},{"id":"glyph-kai-9ed4","script":"kai","character":"黔","reading":"qián","description":"qián：(1)黑色～首。\n(2)中国贵州省的别称～剧（贵州地方戏曲剧种）。～驴技穷。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-黔"},{"id":"glyph-kai-9ed8","script":"kai","character":"默","reading":"mò","description":"mò：不说话，不出声～认。～写。～许。～哀。～诵。～读。～悼。～契。沉～。～～无闻。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-默"},{"id":"glyph-kai-9eef","script":"kai","character":"黯","reading":"àn","description":"àn：昏黑～淡。～然。～～。～黑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-黯"},{"id":"glyph-kai-9f0e","script":"kai","character":"鼎","reading":"dǐng","description":"dǐng：(1)古代烹煮用的器物，一般是三足两耳铜～。～食（列鼎而食，指豪侈生活）。～镬。\n(2)锅～罐。～锅。\n(3)古代视为立国的重器，是政权的象征～彝。九～。定～。问～。～祚（国运）。\n(4)象征三方并立、互相对峙～峙。～足之势。\n(5)大～族。～臣。～力支持。\n(6)正当，正在～盛（shèng）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鼎"},{"id":"glyph-kai-9f13","script":"kai","character":"鼓","reading":"gǔ","description":"gǔ：(1)打击乐器，圆柱形，中空，两头蒙皮～乐（yuè）。～角（jiǎo）。大～。\n(2)形状、声音、作用像鼓的耳～。石～。\n(3)敲击或拍打使发出声音～吹。～噪。\n(4)发动，使振作起来～励。～动。～舞。一～作气。\n(5)高起，凸出～包。～胀。\n(6)古代夜间击鼓以报时，一鼓即一更。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鼓"},{"id":"glyph-kai-9f20","script":"kai","character":"鼠","reading":"shǔ","description":"shǔ：(1)哺乳动物的一科，门齿终生持续生长，常借啮物以磨短，繁殖迅速，种类甚多，有的能传播鼠疫等病原，并为害农林草原，盗食粮食，破坏贮藏物、建筑物等（俗称耗子”）老～。～胆。～目寸光。投～忌器。～辈。\n(2)隐忧～思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鼠"},{"id":"glyph-kai-9f3b","script":"kai","character":"鼻","reading":"bí","description":"bí：嗅觉器官，亦是呼吸的孔道～子。～窦。～孔。～腔。～涕。～音。～烟（由鼻孔吸入的粉末状的烟）。仰人～息。嗤之以～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鼻"},{"id":"glyph-kai-9f50","script":"kai","character":"齐","reading":"qí","description":"整齐\n平等\n⒈一致，不乱，一同，等同～心。整～。一～。百花～放。水深～腰。\n⒉全，完全～全。人到～了。\n⒊治理～家。～民。\n⒋周代诸侯国名，战国时七雄之一，在今山东东北及河北东南一带。\n⒌朝代名\n①南朝之一，又称\"南齐\"，公元479-502年。第一代君主是萧道成。\n②北朝之一，又称\"北齐\"，公元550-577年。第一代君主是高洋。\n齐jī 1.通\"跻\"。升;登。 2.通\"齑\"。指用酱拌和切碎的菜和肉。泛指酱菜或腌菜。\n齐zhāi 1.庄重;严肃恭敬。 2.古人在祭祀或其他典礼前整洁身心，以示庄敬。 3.古人祭祀或典礼所居的宫室，所用的器物。参见\"齐宫\"﹑\"齐服\"﹑\"齐牛\"。\n齐jì 1.后作\"剂\"。将多种药料按一定比例配制而成的药物。 2.泛指药料。 3.后作\"剂\"。调剂;调和。 4.后作\"剂\"。酌量。 5.后作\"剂\"。分量。 6.后作\"剂\"。量词\n。多用以计量药物。 7.后作\"剂\"。指调味品。 8.后作\"剂\"。差别。 9.带糟的浊酒。 10.引申指酿造。 11.合金。 12.界限。 13.指极限。 14.限制;局限。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-齐"},{"id":"glyph-kai-9f7f","script":"kai","character":"齿","reading":"chǐ","description":"排列如齿状的物品\n指年龄\n①人或某些动物咀嚼食物的器官，由坚固的骨组织和釉质构成。通称牙或牙齿。\n②呈齿形的东西锯～。\n④说到；提及何足挂～。\n【齿及】说到。\n【齿冷】耻笑；讥笑令人～。\n【齿轮】周边均匀分布着许多齿的轮子，是机器上最常用、最重要的零件之一。\n【齿鸟类】〈生〉古代鸟类。有牙无翅，脚发达。化石多在白垩纪土层中发现。\n⒈门牙，泛指牙齿唇～相依。唇亡～寒。犬～。臼～。\n⒉排列像齿状的东西～轮。钢锯～。\n⒋提及，说到～及。挂～。不足～数。为人所不～。\n⒌〈古〉并列，排列百官以此相～。\n⒍〈古〉录用循名责实，虚伪不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-齿"},{"id":"glyph-kai-9f84","script":"kai","character":"龄","reading":"líng","description":"年限;年数\n生物学上指某些动植物生长期中划分的阶段\n⒈岁数年～。\n⒉年数工～。教～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-龄"},{"id":"glyph-kai-9f99","script":"kai","character":"龙","reading":"lóng","description":"能升天,神其物,而命之曰灵。”\n⒈〈古〉传说中的一种神异动物，有鳞、有角、有脚，能走、能飞、能游泳，还能兴云降雨飞～乘云。叶公好～。\n⒉〈古〉生物学上指一些早已绝灭的巨大爬行动物恐～。翼手～。\n⒊封建时代象征帝王或指帝王使用的东西～颜。～袍。\n龙máng 1.通\"尨\"。杂色，色斑驳。 2.通\"?\"。参见\"龙鵤\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-龙"},{"id":"glyph-kai-9f9f","script":"kai","character":"龟","reading":"guī","description":"即金龟,亦称乌龟\n黑色,雌体呈棕色,腹面略带黄色,均有暗褐色斑纹,四肢较扁平,有爪,指、趾间具全蹼,产于中国、朝鲜和日本,其腹甲可入药\n龟甲\n⒈同\"皲\"～裂。\n⒉见jūn;qiū。\n⒈爬行动物。腹部及背部都有硬甲，通常头尾和脚能缩入甲中。种类很多，如乌～、棱皮～。玳瑁等。乌龟甲叫\"龟板\"，可供药用。\n⒌见jūn㈡、qiū㈡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-龟"},{"id":"glyph-seal-4e00","script":"seal","character":"一","reading":"yī","description":"yī：(1)数名，最小的正整数（在钞票和单据上常用大写壹”代）。\n(2)纯；专专～。～心～意。\n(3)全；满～生。～地水。\n(4)相同～样。颜色不～。\n(5)另外的蟋蟀～名促织。\n(6)表示动作短暂，或是一次，或具试探性算～算。试～试。\n(7)乃；竞～至于此。\n(8)部分联成整体统～。整齐划～。\n(9)或者～胜～负。\n(10)初次～见如故。\n(11)助词，表示程度深吏呼～何怒，妇啼～何苦！”\n(12)中国古代乐谱记音符号，相当于简谱7”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-一"},{"id":"glyph-seal-4e01","script":"seal","character":"丁","reading":"dīng；zhēng","description":"dīng：(1)天干的第四位，用于作顺序第四的代称～是～，卯是卯。\n(2)成年男子。\n(3)人口。\n(4)从事某种劳动的人园～。\nzhēng：〔～～〕象声词，形容伐木、下棋、弹琴的声音。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丁"},{"id":"glyph-seal-4e03","script":"seal","character":"七","reading":"qī","description":"qī：(1)数名，六加一（在钞票和单据上常用大写柒”代）。\n(2)文体名，或称七体”，为赋体的另一种形式。\n(3)旧时人死后每隔七天一祭，共七次，称做七”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-七"},{"id":"glyph-seal-4e07","script":"seal","character":"万","reading":"wàn","description":"虫名。蝎。\n古代的一种舞名\n古州名\n⒈数目字十千为一～。\n⒉多，一切～般。～物。千家～户。千军～马。～象更新。\n⒊极，很，绝对～端。～难。～无一失。～全之策。\n①万分之一。\n②意外，意外的～一出错。防止～一。\n③倘若，如果～一他不干，就请别人干。\n①千秋万代，永远存在。\n②〈表〉欢呼或棕人民～岁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-万"},{"id":"glyph-seal-4e08","script":"seal","character":"丈","reading":"zhàng","description":"zhàng：(1)中国市制长度单位，十尺万～高楼。\n(2)测量长度和面积～量（liáng）。\n(3)对老年男子的尊称～人（a.古代对老人的尊称；b.岳父。人”均读轻声）。老～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丈"},{"id":"glyph-seal-4e09","script":"seal","character":"三","reading":"sān","description":"sān：(1)数名，二加一（在钞票和单据上常用大写叁”代）～维空间。～部曲。～国（中国朝代名）。\n(2)表示多次或多数～思而行。～缄其口。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-三"},{"id":"glyph-seal-4e0a","script":"seal","character":"上","reading":"shàng；shǎng","description":"shàng：(1)位置在高处的，与下”相对楼～。～边。\n(2)次序或时间在前的～古。～卷。\n(3)等级和质量高的～等。～策。～乘（佛教用语，一般借指文学艺术的高妙境界或上品）。\n(4)由低处到高处～山。～车。～升。\n(5)去，到～街。\n(6)向前进冲～去。\n(7)增加～水。\n(8)安装，连缀～刺刀。～鞋（亦作绱鞋”）。\n(9)涂～药。\n(10)按规定时间进行或参加某种活动～课。～班。\n(11)拧紧发条～弦。\n(12)登载，记～账。\n(13)用在名词后边，表示时间、处所、范围晚～。桌～。组织～。\n(14)用在动词后边，表示开始、继续、趋向、完成爬～来。锁～。选～代表。\n(15)达到一定的程度或数量～年纪。\n(16)中国古代乐谱的记音符号，相当于简谱1”的高音。\n下；\nshǎng：〔～声〕汉语声调之一，普通话上声（第三声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-上"},{"id":"glyph-seal-4e0b","script":"seal","character":"下","reading":"xià","description":"xià：(1)位置在低处的，与上”相对～层。～款。\n(2)等级低的～级。～品。～乘（佛教用语，一般借指文学艺术的平庸境界或下品）。～里巴人（泛指通俗的普及的文学艺术，常与阳春白雪”对举）。\n(3)方面，方位两～都同意。\n(4)次序或时间在后的～卷。～次。～限。\n(5)由高处往低处，降落～山。～车。～马。～达。\n(6)使降落～半旗。～棋。\n(7)进入～海。\n(8)投送～书。\n(9)到规定时间结束日常工作或学习～班。～课。\n(10)谦辞在～。～官。\n(11)颁布～令。\n(12)攻克攻～。\n(13)卸掉～货。把他的枪～了。\n(14)用，投入精力～工夫。\n(15)退让争执不～。\n(16)做出判断～结论。\n(17)量词，指动作次数打三～。\n(18)用在名词后边（ａ．表示在里面，如心～”、言～”；ｂ．表示当某个时节，如节～”、年～”）。\n(19)用在动词后边（ａ．表示关系，如教导～”、培养～”；ｂ．表示完成或结果，如打～基础”；ｃ．与来”、去”连用表示趋向或继续，如走～去”、停～来”）。\n(20)少于不～二百人。\n(21)动物生产鸡～蛋。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-下"},{"id":"glyph-seal-4e0d","script":"seal","character":"不","reading":"bù","description":"用在动词、形容词或个别副词前,表示否定","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-不"},{"id":"glyph-seal-4e0e","script":"seal","character":"与","reading":"yǔ","description":"则与斗卮酒。\n⒈跟，同，和～众不同。～虎谋皮。我～你们一道走。\n⒉给，授予交～。送～。赠～。\n⒋赞许，帮助朝过夕改，君子～之。君不～胜者，而～不胜者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-与"},{"id":"glyph-seal-4e0f","script":"seal","character":"丏","reading":"miǎn","description":"遮蔽，隐蔽。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e10","script":"seal","character":"丐","reading":"gài","description":"gài：(1)乞求。\n(2)讨饭的人乞～。\n(3)给与、施与沾～后人多矣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丐"},{"id":"glyph-seal-4e11","script":"seal","character":"丑","reading":"chǒu","description":"可恶\n污秽\n①丑陋；难看。\n②令人厌恶或瞧不起的～态百出、丢～。\n③戏曲角色。扮演滑稽人物，鼻梁上抹白粉，有文丑、武丑的区别。又叫小花脸或三花脸。\n④地支的第二位。\n⑤姓。\n【丑剧】指丑恶的富有戏剧性的事件。\n【丑类】指恶人，坏人。\n【丑时】旧式计时法指夜里1点到3点的时间。\n⒈地支的第二位，也用作次序第二。\n⒊戏曲、杂技里的一种角色～角。\n⒋相貌难看，跟\"美\"相对～陋。〈喻〉可耻的、可厌恶的或不光荣的～事。现～。家～外扬。～态百出。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丑"},{"id":"glyph-seal-4e13","script":"seal","character":"专","reading":"zhuān","description":"纺专,收丝器\n专长\n独占;独用\n⒈独，独有，独占～断。～利。～权。～制。独断～行。\n⒉单纯，单一，集中在某一方面～注。～一。～心。～业。～选重担挑。\n①特定的门类～门学问。\n专tuán 1.聚集。参见\"尃生\"。 2.圆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-专"},{"id":"glyph-seal-4e14","script":"seal","character":"且","reading":"qiě；jū","description":"qiě：(1)尚，还，表示进一层既高～大。尚～。况～。\n(2)表示暂时苟～偷安。姑～。\n(3)表示将要、将近城～拔矣。年～九十。\n(4)一面这样，一面那样～走～说。\n(5)表示经久这双鞋～穿呢！\n(6)文言发语词，用在句首，与夫”相似～说。\n(7)姓。\njū：(1)文言助词，用在句末，与啊”相似。\n(2)多的样子。\n(3)农历六月的别称。\n(4)敬慎的样子有萋有～”。\n(5)古同趄”，趑趄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-且"},{"id":"glyph-seal-4e15","script":"seal","character":"丕","reading":"pī","description":"pī：大～业。～变。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丕"},{"id":"glyph-seal-4e16","script":"seal","character":"世","reading":"shì","description":"shì：(1)一个时代，有时特指三十年～代（a.很多年代；b.好几辈子）。～纪（指一百年）。流芳百～。\n(2)一辈一辈相传的～袭。～家（a.封建社会中门第高，世代做官的人家；b.《史记》中诸侯的传记）。\n(3)人间，以与天上相区别～上。～俗（a.流俗；b.非宗教的）。～故（a.处事待人圆滑，故”读轻声；b.处世经验）。～态炎凉。\n(4)自然界和人类社会一切事物的总和；全地球、人间或宇宙；宇宙的一部分～界。举～瞩目。公之于～。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-世"},{"id":"glyph-seal-4e18","script":"seal","character":"丘","reading":"qiū","description":"qiū：(1)小土山土～。沙～。～陵。～壑。\n(2)像小土山凸起的～疹。\n(3)坟墓～墓（大墓）。～垄。\n(4)量词，指用田塍隔开的水田一～十亩大的小田。\n(5)众人聚居的地方～民（乡民，邑民）。\n(6)用砖石封闭有尸体的棺材。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丘"},{"id":"glyph-seal-4e19","script":"seal","character":"丙","reading":"bǐng","description":"bǐng：(1)天干的第三位，用作顺序第三的代称。\n(2)火的代称（五行中丙”、丁”属火）付～（把信件等烧掉）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丙"},{"id":"glyph-seal-4e1a","script":"seal","character":"业","reading":"yè","description":"版,大版\n古代覆在悬挂钟、鼓等乐器架横木上的装饰物,刻如锯齿形,涂以白色\n筑墙版\n古代书册之版\n⒈事情，所从事的工作事～。创～。功～。\n⒉生产或经济部门农～。工～。行～。商～。\n⒊职务，工作岗位职～。就～。转～。\n⒋学习的功课学～。毕～。\n⒌财产产～。家～。\n⒍从事～农。～工。\n⒎已经～已。～经。\n⒏梵语\"羯磨\"的义译，意为\"造作\"。佛教称人的言行、思念为业。分身～、口～、意～，统称三～。又分善与恶，一般都指恶～。\n①高大健壮的样子四牡～ ～。\n②担心害怕的样子兢兢～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-业"},{"id":"glyph-seal-4e1b","script":"seal","character":"丛","reading":"cóng","description":"许多事物凑在一起\n众多;繁杂\n①聚集～集、杂草～生。\n②一簇簇的草木草～、花～。\n③泛指聚集在一起的人或物～书、人～。\n④姓。\n【丛刊】见【丛书】。\n【丛葬】很多尸体合埋的方式，也指这样的坟墓。\n【丛冢】乱葬在一处的许多坟墓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丛"},{"id":"glyph-seal-4e1c","script":"seal","character":"东","reading":"dōng","description":"方位名，太阳升起的一方，与西相对。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e1d","script":"seal","character":"丝","reading":"sī","description":"⒈蚕吐出的纤维。它是绸、缎等的原料新～。\n⒉像丝的东西蛛～。铁～。肉～儿。\n⒊细微，极少，细致一～不苟。～毫不差。～ ～入扣。\n⒋计量单位十～为一毫。百～为一厘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丝"},{"id":"glyph-seal-4e1e","script":"seal","character":"丞","reading":"chéng","description":"chéng：(1)帮助，辅佐～相（古代辅佐帝王治理国家大事的统率百官的最高大臣）。\n(2)封建时代辅佐主要官员做事的官吏府～。县～。\n(3)古同承”，秉承。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丞"},{"id":"glyph-seal-4e24","script":"seal","character":"两","reading":"liǎng","description":"双。用于鞋娄\n通辆”。车一乘\n武王戎车三\n⒈数目字\n④新的度量衡单位前，一般用\"两\"～米。～吨。\n⑤形容词前做状语，只能用\"两\"不能用\"二\"势不～立。\n两liàng 1.量词。用于车辆。 2.借指车。 3.容纳一辆车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-两"},{"id":"glyph-seal-4e25","script":"seal","character":"严","reading":"yán","description":"严厉;严肃\n⒈紧密，没有缝隙～密。将瓶口封～。\n⒉认真，不放松～格要求。～厉惩办。～于律己。〈转义〉父亲家～。\n⒊猛烈，厉害～风。～寒。\n⒋急，极其重大的，紧急措施事～。～重。戒～。解～。\n严yǎn 1.庄严貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-严"},{"id":"glyph-seal-4e27","script":"seal","character":"丧","reading":"sàng","description":"⒈失掉，死亡～失。～胆。～命。\n①事情进行不顺利而情绪低落垂头～气。\n②迷信者所谓\"不吉利\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丧"},{"id":"glyph-seal-4e2a","script":"seal","character":"个","reading":"gè","description":"通用个体量词,表示单独的人或物\n字亦作箇”\n俗又作個”\n用于没有专用量词的事物。如一个人;一个影子\n也可用于某些有专用量词的事物\n⒈单，独～人。～别。～体。\n⒉量词洗了～澡。两～苹果。三～月。竹竿万～。\n⒊此，这～中。～样。\n⒋〈表〉动作行为打他～落花流水。\n⒌〈表〉身材或物体的大小瘦～儿。包子～儿不小。\n⒍〈表〉程度或持续笑～不停。讲～没完。\n⒎语气助词。无义明儿～。\n个gàn 1.古代射礼用的箭靶两旁上下伸出的部分，又叫舌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-个"},{"id":"glyph-seal-4e2d","script":"seal","character":"中","reading":"zhōng；zhòng","description":"zhōng：中间，内部；居中。zhòng：正对上，受到或达到，如命中、中选、中毒。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e30","script":"seal","character":"丰","reading":"fēng","description":"中国古代礼器,形状像豆,用以承酒觯\n蒲草\n地名\n周国都名\n秦沛县之丰邑,汉置县\n⒈富，盛，多，大 ～盛。～硕。～富多彩。～衣足食。～功伟绩。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丰"},{"id":"glyph-seal-4e34","script":"seal","character":"临","reading":"lín","description":"引申为从上监视着\n⒉到，遇到身～其境。双喜～门。～渴掘井。\n⒊将要～走。～别。\n⒋面对，挨着，靠近～战。～街。～危不惧。\n⒌对照着字、画摹仿～帖。～摹。\n⒍〈古〉帝王上朝～朝。～政。\n①到时候，当时事先准备好，免得～时着急。\n②暂时，短期，非经常的～时措施。\n临lìn 1.哭吊死者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-临"},{"id":"glyph-seal-4e38","script":"seal","character":"丸","reading":"wán","description":"wán：(1)小而圆的东西弹（dàn）～。肉～儿。\n(2)专指药丸”～散膏丹。～药。\n(3)量词，用于丸药吃两～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丸"},{"id":"glyph-seal-4e39","script":"seal","character":"丹","reading":"dān","description":"dān：(1)红色～砂（朱砂）。～桂（观赏植物，花为橘红色）。～心碧血（赤诚的忠心，珍贵的热血）。～青。\n(2)依成方制成的颗粒状或粉末状的中药丸散膏～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丹"},{"id":"glyph-seal-4e3a","script":"seal","character":"为","reading":"wéi；wèi","description":"wéi：做，成为，担任；是；被。wèi：替、给；为了；对、向。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e3b","script":"seal","character":"主","reading":"zhǔ","description":"zhǔ：(1)权力或财物的所有者，家庭的首脑～人。物～。失～（失掉财物的人）。当家作～。\n(2)旧时臣子称君王，下级称上级，仆人称家主君～。～上。\n(3)对事物的意见或认为应当如何处理，决定～张。～见。～意。～义。\n(4)对事物有决定权力民～。自～。～持。～宰。～权（一个国家的独立自主的权力）。\n(5)最重要的，最基本的～次。～要。～力。～将（jiàng）。\n(6)预示早霞～雨。\n(7)旧时为死人立的牌位木～。神～。\n(8)基督教、伊斯兰教对所信仰的神或本教创始人的称呼。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-主"},{"id":"glyph-seal-4e3d","script":"seal","character":"丽","reading":"lì","description":"通罹”。遭遇;落入\n丽水\n成对◇作俪”\n⒈漂亮，好看～人。太美～。非常壮～。风和日～。\n⒉附着附～。\n⒊见likz。\n丽lǐ 1.数目。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-丽"},{"id":"glyph-seal-4e3e","script":"seal","character":"举","reading":"jǔ；jv","description":"拿起;提起\n飞,飞起;飘动\n⒈抬起，向上托～头。～手。～枪。～案齐眉。〈引〉\n①行动，动作～动。创～。一～成名。\n②发起，兴办～义。～办工厂。\n⒉提出～例。列～。\n⒊推选，推荐推～。选～。\n⒋全～国欢腾。～世无双。\n⒌揭发检～。\n①点火。\n②生火做饭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-举"},{"id":"glyph-seal-4e42","script":"seal","character":"乂","reading":"yì","description":"治理，安定；也指有才德的人。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e43","script":"seal","character":"乃","reading":"nǎi","description":"nǎi：(1)才今～得之。断其喉，尽其肉，～去”。\n(2)是，为～大丈夫也。\n(3)竟～至如此。\n(4)于是，就因山势高峻，～在山腰休息片时”。\n(5)你，你的～父。～兄。家祭无忘告～翁”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乃"},{"id":"glyph-seal-4e45","script":"seal","character":"久","reading":"jiǔ","description":"jiǔ：(1)时间长～远。～经。～已。～违（客套话，好久没见）。～仰（初次见面客套话，仰慕已久）。～别重逢。～而～之。\n(2)时间的长短住多～？三年之～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-久"},{"id":"glyph-seal-4e48","script":"seal","character":"么","reading":"me；yāo；ma","description":"yāo：同幺”。\nm：同吗3”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-么"},{"id":"glyph-seal-4e49","script":"seal","character":"义","reading":"yì","description":"义不杀少。\n情谊\n⒈公正合宜的道德、道理或行为正～。～愤填膺。～正辞严。见～勇为。多行不～，必自毙。\n⒉意思，含意意～。字～。释～。望文生～。\n⒊情谊有情有～。\n①应尽的责任尽～务。\n②不拿报酬的～务劳动。\n义yí 1.仪容;状貌。 2.仪制;法度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-义"},{"id":"glyph-seal-4e4b","script":"seal","character":"之","reading":"zhī","description":"zhī：(1)助词，表示领有、连属关系赤子～心。\n(2)助词，表示修饰关系缓兵～计。不速～客。莫逆～交。\n(3)用在主谓结构之间，使成为句子成分大道～行也，天下为公”。\n(4)代词，代替人或事物置～度外。等闲视～。\n(5)代词，这，那～二虫，又何知”。\n(6)虚用，无所指久而久～。\n(7)往，到吾欲～南海”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-之"},{"id":"glyph-seal-4e4c","script":"seal","character":"乌","reading":"wū","description":"古代神话传说太阳中有三足乌,因以乌”为太阳的代称\n刚孵化出的幼蚕\n浅黑色\n身披乌衣,手执耒耜,以率将\n⒉黑色～衣。～云。～烟。\n⒊文言副词。哪，何，怎么土～能神？\n乌yā 1.地名用字。\n乌wù 1.见\"乌拉\"﹑\"乌拉草\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乌"},{"id":"glyph-seal-4e4d","script":"seal","character":"乍","reading":"zhà","description":"zhà：(1)忽然～冷～热。～暧还寒。\n(2)刚，起初新来～到。\n(3)张开，鼓起～着胆子（勉强鼓起勇气）。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乍"},{"id":"glyph-seal-4e4e","script":"seal","character":"乎","reading":"hū","description":"hū：(1)文言助词，表示疑问汝识之～（吗）？\n(2)文言叹词陛下与谁取天下～（呀）！\n(3)文言介词，相当于”（用在动词或形容词后）在～。无须～。异～寻常。\n(4)古形容词或副词后缀巍巍～。郁郁～。\n(5)古同呼”，呜呼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乎"},{"id":"glyph-seal-4e4f","script":"seal","character":"乏","reading":"fá","description":"fá：(1)缺少～味。贫～。不～其人。\n(2)疲倦～困。～累。疲～。\n(3)无能，无用～气。～煤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乏"},{"id":"glyph-seal-4e50","script":"seal","character":"乐","reading":"lè；yuè","description":"lè：快乐，喜悦；喜欢做某事。yuè：音乐；乐器；姓氏。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e54","script":"seal","character":"乔","reading":"qiáo","description":"高耸。多用以形容树木\n詈词。宋元以后,曲中用乔者甚多,常随文为释,含有坏、窝囊、糊涂、狡猾、怯懦无用等贬义。形容某种恶劣的表现\n⒉假、伪～装。～妆打扮。\n乔jiāo 1.骄横放纵。\n乔jiǎo 1.见\"乔诘\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乔"},{"id":"glyph-seal-4e56","script":"seal","character":"乖","reading":"guāi","description":"guāi：(1)不顺，不和谐～舛（谬误）。～谬。～戾（性情、言语、行为别扭，不合情理）。～僻（怪僻）。～张（怪僻，不讲情理）。出～露丑。\n(2)机灵，伶俐（多指小孩听话）～～。～巧。卖～。～觉（jué）。～顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乖"},{"id":"glyph-seal-4e58","script":"seal","character":"乘","reading":"chéng；shèng","description":"chéng：(1)骑，坐～马。～车。～客。～警。\n(2)趁着，就着～便。～机（趁着机会）。～势。～兴（xìng）。因利～便。\n(3)算术中指一个数使另一个数变成若干倍～法。～幂（mì）。～数。\n(4)佛教的教派或教法大～。小～。上～。下～。\n(5)姓。\nshèng：(1)古代称兵车，四马一车为一乘～舆。千～之国。\n(2)古代称四为乘～矢。～壶。以～韦先牛十二犒师”。\n(3)中国春秋时晋国的史书称乘”，后通称一般的史书史～。野～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乘"},{"id":"glyph-seal-4e59","script":"seal","character":"乙","reading":"yǐ","description":"yǐ：(1)天干的第二位，用于作顺序第二的代称。\n(2)指代一方甲方～方。～型脑炎。\n(3)中国古代乐谱的记音符号，相当于简谱7”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乙"},{"id":"glyph-seal-4e5d","script":"seal","character":"九","reading":"jiǔ","description":"jiǔ：(1)数目，八加一（在钞票和单据上常用大写玖”代）～归。\n(2)泛指多次或多数～死一生。～霄云外。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-九"},{"id":"glyph-seal-4e5f","script":"seal","character":"也","reading":"yě","description":"yě：(1)副词，表示同样、并行的意思你去，我～去。\n(2)在否定句里表示语气的加强一点儿～不错。\n(3)在复句中表转折意虽然你不说，我～能猜个八九不离十。\n(4)文言语气助词（a.表判断；b.表疑问；c.表停顿；d.形容词尾）。\n(5)表示容忍或承认某种情况～罢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-也"},{"id":"glyph-seal-4e60","script":"seal","character":"习","reading":"xí","description":"反覆练习,钻研\n⒈鸟屡次拍着翅膀飞鹰乃学～。\n⒉反复练，反复学，学后再温熟练～。复～。学～。自～。温～。\n⒊通晓，熟悉～地形。～水性。\n⒋长期反复地做，逐渐养成的不自觉的活动～惯。积～。恶～。相沿成～。〈引〉常常地～见。～闻。\n①鸟飞来飞去～ ～笼中鸟。\n②形容微风吹拂凉风～ ～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-习"},{"id":"glyph-seal-4e66","script":"seal","character":"书","reading":"shū","description":"乃丹书帛曰陈胜王”,置人所罾鱼\n⒈写，记载～写。奋笔疾～。大～特～。\n⒉文字读其～。读～破万卷。\n⒊信家～。来～已收。\n⒋文件证～。决心～。倡议～。\n⒌装订成册的著作～籍。著～立说。\n⒍字体楷～。行～。草～。\n⒏称某些曲艺说～。鼓～。\n①汉字的书写法则。\n②汉字的书写艺术，也省称\"书\"～画展览。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-书"},{"id":"glyph-seal-4e70","script":"seal","character":"买","reading":"mǎi","description":"雇,租\n⒈用货币换东西，跟\"卖\"相反购～。～轿车。～飞机。〈引〉用钱财或其它手段取得～通。\n①采购货物的人。\n②殖民地、半殖民地国家中，为外国资本家服务，经营银行、工矿、运输、商品等业务的中间人或经纪人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-买"},{"id":"glyph-seal-4e71","script":"seal","character":"乱","reading":"luàn","description":"治理\n扰乱;打乱;使乱\n淫乱,\n⒈无秩序，无条理纷～。杂～。～七八糟。\n⒉骚扰，战争动～。叛～。扰～。兵～。\n⒊混淆以假～真。\n⒋任意，随便～说～动。\n⒌男女关系不正常淫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乱"},{"id":"glyph-seal-4e73","script":"seal","character":"乳","reading":"rǔ","description":"rǔ：(1)分泌奶的器官～房（亦称乳”、奶子”）。～峰。～罩。\n(2)乳房中分泌出来的白色甜汁～汁（亦称奶”）。哺～。～母（奶妈）。～臭（xiù）未干（对年幼人表示轻蔑）。\n(3)像乳汁的东西豆～。～胶。～腐（亦称腐乳”）。\n(4)像乳头的东西钟～（钟上可敲打的突出物）。钟～石。\n(5)生，生殖孳～。\n(6)初生的、幼小的～燕。～牙。～名（小名）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乳"},{"id":"glyph-seal-4e7e","script":"seal","character":"乾","reading":"qián；gān","description":"qián：(1)八卦之一，代表天～坤（坤”，代表地）。\n(2)旧时称男性的～造。～宅。\n坤；\ngān：见干1”⑨～??。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-乾"},{"id":"glyph-seal-4e86","script":"seal","character":"了","reading":"le；liǎo","description":"le：助词，表示动作完成或情况变化。liǎo：完结；明白，如了结、了解。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-4e88","script":"seal","character":"予","reading":"yǔ；yú","description":"yú：同余”，我～智自雄（自夸聪明，妄自夸大）。～取～求（原指从我这里取，从我这里求；后指任意索取）。\n夺；取；\nyǔ：给与～以。赐～。赋～。给～。生杀～夺（亦作生杀与夺”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-予"},{"id":"glyph-seal-4e89","script":"seal","character":"争","reading":"zhēng","description":"zhēng：(1)力求获得，互不相让～夺。竞～。～长论短。\n(2)力求实现～取。～气。～胜。\n(3)方言，差，欠总数还～多少？\n(4)怎么，如何（多见于诗、词、曲）～不。～知。～奈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-争"},{"id":"glyph-seal-4e8b","script":"seal","character":"事","reading":"shì","description":"shì：(1)自然界和社会中的现象和活动～情。～件。～业。\n(2)变故～故（出于某种原因而发生的不幸事情，如工作中的死伤等）。～端。\n(3)职业谋～（指找职业）。\n(4)关系和责任你走吧，没你的～了。\n(5)办法光着急也不是～儿，还得另找出路。\n(6)做，治不～生产。无所～事。\n(7)服侍～父母。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-事"},{"id":"glyph-seal-4e8c","script":"seal","character":"二","reading":"èr","description":"èr：(1)数名一加一（在钞票和单据上常用大写贰”代）。\n(2)双，比独一无～。\n(3)两样，别的～话。不～价。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-二"},{"id":"glyph-seal-4e8e","script":"seal","character":"于","reading":"yú","description":"yú：(1)介词（ａ．在，如生～北京”；ｂ．到，如荣誉归～老师”；ｃ．对，如勤～学习”；ｄ．向，如出～自愿”；ｅ．给，如问道～盲”；ｆ．自，从，如取之～民”；ｇ．表比较，如重～泰山”；ｈ．表被动，如限～水平”）。\n(2)后缀（ａ．在形容词后，如疏～防范”；ｂ．在动词后，如属～未来）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-于"},{"id":"glyph-seal-4e8f","script":"seal","character":"亏","reading":"kuī","description":"损耗,损害\n⒈欠缺，短少～斤少两。自感理～。月满则～。功～一篑。\n⒊亏负，对不起不做～心事。他不会～人。\n⒋幸而，多亏幸～。这件事～你帮忙。\n⒌〈表〉讥讽～你干得出来！\n⒍毁坏，损害不～不崩。～败风俗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亏"},{"id":"glyph-seal-4e91","script":"seal","character":"云","reading":"yún","description":"由微小水滴或冰晶组成、漂浮在大气中的云。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-4e92","script":"seal","character":"互","reading":"hù","description":"hù：彼此～相。～助。～利。～生。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-互"},{"id":"glyph-seal-4e94","script":"seal","character":"五","reading":"wǔ","description":"wǔ：(1)数名，四加一（在钞票和单据上常用大写伍”代）～彩。～官。～谷。～金。～代（中国朝代名，后梁、后唐、后晋、后汉、后周先后在中原建立政权的时期）。～帝（中国传说中的五个帝王，通常指黄帝、颛顼、帝喾、唐尧、虞舜）。～毒（指蝎、蛇、蜈蚣、壁虎、蟾蜍）。～行（指金、木、水、火、土）。～岭（指越城岭，都庞岭，萌渚岭、骑田岭、大庾岭）。～岳（指东岳泰山、西岳华山、南岳衡山、北岳恒山和中岳嵩山，是中国历史上五大名山）。～脏（指心、肝、脾、肺、肾）。\n(2)中国古代乐谱的记音符号，相当于简谱6”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-五"},{"id":"glyph-seal-4e95","script":"seal","character":"井","reading":"jǐng","description":"jǐng：(1)人工挖成的能取出水的深洞。水～。临渴掘～。\n(2)形状像井的天～。油～。\n(3)整齐，有秩序～然。～～有条。\n(4)星名，二十八宿之一。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-井"},{"id":"glyph-seal-4e98","script":"seal","character":"亘","reading":"gèn","description":"gèn：空间和时间上延续不断横～。绵～数千里。～古（整个古代，终古，如～～未有”、～～奇闻”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亘"},{"id":"glyph-seal-4e9a","script":"seal","character":"亚","reading":"yà","description":"次;次于。表示时间或空间的先后\n⒈次，第二的～热带。～军。\n⒉较差我不～于他。\n⒊〈外〉亚洲，全称\"亚细亚洲\"，世界七大洲之一。\n亚wù 1.厌恶，憎恶。\n亚yā 1.象声词。 2.助词。犹阿，多用在亲属称呼前，无义。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亚"},{"id":"glyph-seal-4e9b","script":"seal","character":"些","reading":"xiē；suò","description":"xiē：(1)表示不定的数量一～。某～。～微。～许。\n(2)用在形容词后表示比较的程度病轻～了。\nsuò：《楚词》中的句末助词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-些"},{"id":"glyph-seal-4e9f","script":"seal","character":"亟","reading":"jí；qì","description":"jí：急切～～。～待解决。～须纠正。\nqì：屡次～请（屡次请求）。～来问讯。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亟"},{"id":"glyph-seal-4ea1","script":"seal","character":"亡","reading":"wáng；wú","description":"wáng：(1)逃逃～。流～。\n(2)失去～佚。～羊补牢。\n(3)死伤～。死～。\n(4)灭灭～。～国奴。救～。兴～。\n灭；殁；卒；\n兴；存；\nwú：古同无”，没有。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亡"},{"id":"glyph-seal-4ea2","script":"seal","character":"亢","reading":"kàng","description":"kàng：(1)高，高傲高～。不～不卑。\n(2)极度，非常～旱。～奋。\n(3)抗，匹敌～礼。～衡。\n(4)星名，二十八宿之一。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亢"},{"id":"glyph-seal-4ea4","script":"seal","character":"交","reading":"jiāo","description":"jiāo：(1)付托，付给～活儿。～卷。～差。\n(2)相错，接合～点。～界。～错。～相。～辉。～响乐。\n(3)互相来往联系～流。～易。～涉。\n(4)与人相友好～朋友。～契。\n(5)一齐，同时～并。～作。风雨～加。\n(6)两性和合性～。杂～。\n(7)同跤”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-交"},{"id":"glyph-seal-4ea5","script":"seal","character":"亥","reading":"hài","description":"hài：(1)地支的末一位，属猪。\n(2)用于计时～时（晚九点至十一点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亥"},{"id":"glyph-seal-4ea6","script":"seal","character":"亦","reading":"yì","description":"yì：(1)副词，也，表示同样、也是～无不可。～步～趋。\n(2)又先君何罪？其嗣～何罪？”\n(3)不过，只是王～不好土也，何患无士？”\n(4)表示加强或委婉的语气呜呼，～盛矣哉！”学而时习之，不～说乎？”\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亦"},{"id":"glyph-seal-4ea7","script":"seal","character":"产","reading":"chǎn","description":"出产\n①人或动物的幼体从母体中分离出来～卵。\n②制造；生产国～、减～。\n③出产～粮。\n④产品；物产矿～、土特～。\n⑤产业；财～、遗～。\n【产卵回游】见【生殖回游】。\n【产卵器】〈生〉昆虫雌虫的外生殖器官，由腹部后端几节的附肢变成。有各种形状，膜翅目的多呈针状；麦叶蜂的呈扁形、锯状。\n【产品】生产出来的物品；劳动产品的简称这种汽车是我们厂的～。\n【产褥热】〈医〉产妇在临产过程中和产后10天内，因链球菌从生殖器官侵入体内而引起的一种疾病。症状是持续发高烧，下腹痛，阴道流脓血，头痛，呕吐等。\n【产业革命】\n①见【工业革命】。\n②因国民经济各部门广泛地采用新技术，从而引起的经济发展和产业结构的根本变革。\n【产业工人】指在大工厂、矿山、交通运输等部门从事集体生产劳动的工人。\n【产业后备军】'现役劳动军'的对称。资本主义社会中处于失业和半失业状态的相对过剩人口。是资本家获得廉价劳动力、发展资本主义大工业的主要条件。\n【产业军】从事现代化生产的有组织有纪律的劳动者队伍。资本主义社会的产业军是资产阶级组织的。由被剥削被压迫的雇佣劳动者组成。社会主义社会的产业军与资本主义根\n本不同，它是由作为国家主人的劳动者组成的，摆脱了被剥削被压迫的地位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-产"},{"id":"glyph-seal-4ea8","script":"seal","character":"亨","reading":"hēng；pēng","description":"hēng：(1)通达，顺利～通。～运（旧时指命运亨通太平盛世）。～衢（四通八达的大道）。大～（广有势力的官商或流氓）。\n(2)姓。\npēng：古同烹”，煮。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亨"},{"id":"glyph-seal-4ea9","script":"seal","character":"亩","reading":"mǔ","description":"田垄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-亩"},{"id":"glyph-seal-4eab","script":"seal","character":"享","reading":"xiǎng","description":"xiǎng：(1)受用～福。～乐。～誉。～年（敬辞，享有的年岁，对人或朝代而言）。～受。～用。～有。～国（帝王在位年数）。安～。分～。\n(2)贡献（指把祭品，珍品献给祖先、神明或天子、侯王），上供～堂。～殿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-享"}];
